function normalize(text) {
  if (typeof text !== 'string') return text;
  return text.normalize('NFKC').toLowerCase().replace(/\s+/g, ' ').trim();
}

files.tokenizer.js:
// tokenizer.js — owns tokenize(text)
// Injected by host: normalize(text) from normalize.js

function tokenize(text) {
  var normalized;
  if (typeof normalize !== 'function') {
    throw new Error('normalize(text) must be injected by the host');
  }
  normalized = normalize(text);

  var tokens = [];
  if (typeof normalized !== 'string' || normalized.length === 0) {
    return tokens;
  }

  // Extract ASCII alphanumeric runs with interior ASCII apostrophes:
  // [A-Za-z0-9]+(?:'[A-Za-z0-9]+)*
  var pattern = /[A-Za-z0-9]+(?:'[A-Za-z0-9]+)*/g;
  var match;
  while ((match = pattern.exec(normalized)) !== null) {
    tokens.push(match[0]);
  }
  return tokens;
}

files.pipeline.js:
function processText(text) {
  var tokens = tokenize(text);
  var seen = {};
  var unique = [];
  var frequencies = {};
  for (var i = 0; i < tokens.length; i++) {
    var t = tokens[i];
    if (!Object.prototype.hasOwnProperty.call(seen, t)) {
      seen[t] = true;
      unique.push(t);
      frequencies[t] = 0;
    }
    frequencies[t] += 1;
  }
  return {
    text: tokens.join(' '),
    tokens: tokens,
    count: tokens.length,
    unique: unique,
    frequencies: frequencies
  };
}

